Changes:

src/mix_algos.c
@@ -1,5 +1,5 @@
 /*
- * mix_algos.c — 逐样本算法（四个经典 + tanh 软饱和）
+ * mix_algos.c — 逐样本算法（四个经典 + tanh 软饱和 + 三次软削波）
  *
